<script lang="ts">import {clamp,colors} from '../charts';let {value=0,max=100,label='',caption='',display,color=colors.mint,second,band=null,marker=false,size=100,stroke=9,sweep=270}:{value?:number,max?:number,label?:string,caption?:string,display?:string,color?:string,second?:string,band?:[number,number]|null,marker?:boolean,size?:number,stroke?:number,sweep?:number}=$props();const id=Math.random().toString(36).slice(2);let r=$derived((size-stroke)/2-3),c=$derived(size/2),circ=$derived(2*Math.PI*r),length=$derived(circ*sweep/360),rotation=$derived(90+(360-sweep)/2),fraction=$derived(clamp(value/max)),a=$derived((rotation+sweep*fraction)*Math.PI/180);</script>
<div class="gauge" style:width={size+'px'} style:height={size+'px'}>
<svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style="overflow:visible" aria-hidden="true"><defs><linearGradient id={id} x1="0" y1="1" x2="1" y2="0"><stop stop-color={second??color}/><stop offset="1" stop-color={color}/></linearGradient></defs><g transform={`rotate(${rotation} ${c} ${c})`}><circle cx={c} cy={c} {r} fill="none" stroke="rgba(255,255,255,.08)" stroke-width={stroke} stroke-linecap="round" stroke-dasharray={`${length} ${circ}`}/>{#if band}<circle cx={c} cy={c} {r} fill="none" stroke={color} stroke-opacity=".22" stroke-width={stroke} stroke-dasharray={`0 ${length*clamp(band[0]/max)} ${length*(clamp(band[1]/max)-clamp(band[0]/max))} ${circ}`}/>{/if}<circle cx={c} cy={c} {r} fill="none" stroke={color} stroke-opacity=".10" stroke-width={stroke*2} stroke-linecap="round" stroke-dasharray={`${length*fraction} ${circ}`}/><circle cx={c} cy={c} {r} fill="none" stroke={`url(#${id})`} stroke-width={stroke} stroke-linecap="round" stroke-dasharray={`${length*fraction} ${circ}`}/></g>{#if marker}<circle cx={c+r*Math.cos(a)} cy={c+r*Math.sin(a)} r={stroke*.62} fill="white" stroke={color} stroke-width="3"/>{/if}</svg>
<div class="gauge-center"><b class="n" style:font-size={size>=150?'52px':size<=85?'22px':'27px'}>{display??(max<=5?value.toFixed(1):Math.round(value))}</b>{#if caption}<span>{caption}</span>{/if}{#if label}<em style:color>{label}</em>{/if}</div></div>
<style>.gauge{position:relative;flex:none}.gauge-center{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column}.gauge-center b{font-weight:600;line-height:1}.gauge-center span{font:600 10px Inter;letter-spacing:.14em;text-transform:uppercase;color:var(--text2);margin-top:5px}.gauge-center em{font:700 11px Inter;letter-spacing:.12em;text-transform:uppercase;font-style:normal;margin-top:4px}</style>